-- CPF integration closure lifecycle: field encryption, data quality and webhook
CREATE TABLE CPF_FIELD_ENCRYPTION_LEDGER (
 RECORD_ID VARCHAR2(64 CHAR) NOT NULL, FIELD_NAME VARCHAR2(64 CHAR) NOT NULL, CLASSIFICATION VARCHAR2(64 CHAR) NOT NULL, KEY_VERSION VARCHAR2(64 CHAR) NOT NULL, SEARCH_TOKEN VARCHAR2(1000 CHAR), ENVELOPE_PAYLOAD BLOB NOT NULL, MASKED_PREVIEW VARCHAR2(1000 CHAR) NOT NULL, ROW_VERSION NUMBER(19) NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, PRIMARY KEY (RECORD_ID, FIELD_NAME)
);
CREATE INDEX IX_CPF_FIELD_ENC_TOKEN ON CPF_FIELD_ENCRYPTION_LEDGER (FIELD_NAME, SEARCH_TOKEN);
CREATE TABLE CPF_DATA_QUALITY_RULE (RULE_ID VARCHAR2(64 CHAR) NOT NULL, RULE_VERSION NUMBER(19) NOT NULL, FIELD_NAME VARCHAR2(64 CHAR) NOT NULL, EXPRESSION VARCHAR2(1000 CHAR) NOT NULL, SEVERITY VARCHAR2(64 CHAR) NOT NULL, RULE_STATE VARCHAR2(64 CHAR) NOT NULL, UPDATED_BY VARCHAR2(64 CHAR) NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, PRIMARY KEY (RULE_ID, RULE_VERSION));
CREATE TABLE CPF_DATA_QUALITY_QUARANTINE (QUARANTINE_ID VARCHAR2(64 CHAR) NOT NULL, RECORD_ID VARCHAR2(64 CHAR) NOT NULL, ORIGINAL_PAYLOAD BLOB NOT NULL, CORRECTED_PAYLOAD BLOB, QUARANTINE_STATE VARCHAR2(64 CHAR) NOT NULL, VIOLATION_SUMMARY VARCHAR2(1000 CHAR) NOT NULL, ROW_VERSION NUMBER(19) NOT NULL, UPDATED_BY VARCHAR2(64 CHAR), UPDATE_REASON VARCHAR2(1000 CHAR), UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, PRIMARY KEY (QUARANTINE_ID));
CREATE INDEX IX_CPF_DQ_QUARANTINE_STATE ON CPF_DATA_QUALITY_QUARANTINE (QUARANTINE_STATE, UPDATED_AT);
CREATE TABLE CPF_WEBHOOK_ENDPOINT (ENDPOINT_ID VARCHAR2(64 CHAR) NOT NULL, CALLBACK_URI VARCHAR2(1000 CHAR) NOT NULL, SECRET_VERSION VARCHAR2(64 CHAR) NOT NULL, ALLOWED_EVENT_TYPES VARCHAR2(1000 CHAR) NOT NULL, ENABLED NUMBER(1) NOT NULL, ROW_VERSION NUMBER(19) NOT NULL, UPDATED_BY VARCHAR2(64 CHAR) NOT NULL, UPDATE_REASON VARCHAR2(1000 CHAR) NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, PRIMARY KEY (ENDPOINT_ID));
CREATE TABLE CPF_WEBHOOK_DELIVERY (DELIVERY_ID VARCHAR2(64 CHAR) NOT NULL, ENDPOINT_ID VARCHAR2(64 CHAR) NOT NULL, EVENT_ID VARCHAR2(64 CHAR) NOT NULL, EVENT_TYPE VARCHAR2(64 CHAR) NOT NULL, IDEMPOTENCY_KEY VARCHAR2(64 CHAR) NOT NULL, DELIVERY_SEQUENCE NUMBER(19) NOT NULL, DELIVERY_STATE VARCHAR2(64 CHAR) NOT NULL, ATTEMPT_COUNT NUMBER(19) NOT NULL, NEXT_ATTEMPT_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, LAST_ERROR VARCHAR2(1000 CHAR), ROW_VERSION NUMBER(19) NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, PRIMARY KEY (DELIVERY_ID), CONSTRAINT UK_CPF_WEBHOOK_IDEMP UNIQUE (ENDPOINT_ID, IDEMPOTENCY_KEY));
CREATE INDEX IX_CPF_WEBHOOK_DUE ON CPF_WEBHOOK_DELIVERY (ENDPOINT_ID, DELIVERY_STATE, NEXT_ATTEMPT_AT, DELIVERY_SEQUENCE);
CREATE TABLE CPF_INTEGRATION_CLOSURE_AUDIT (AUDIT_ID VARCHAR2(64 CHAR) NOT NULL, CATEGORY VARCHAR2(64 CHAR) NOT NULL, TARGET_ID VARCHAR2(64 CHAR) NOT NULL, ACTION_NAME VARCHAR2(64 CHAR) NOT NULL, ACTOR_ID VARCHAR2(64 CHAR) NOT NULL, ACTION_REASON VARCHAR2(1000 CHAR) NOT NULL, RESULT_STATE VARCHAR2(64 CHAR) NOT NULL, RESULT_DETAIL VARCHAR2(1000 CHAR), OCCURRED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, PRIMARY KEY (AUDIT_ID));
